package cn.xiaoyanjiu.ff14chat;
import java.nio.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import java.security.*;
final class UdpVideoProtocol {
 static final int CHUNK=1152,HEADER=32,MAX_FRAME=4194304;static final class Packet{final int type,flags,index,count,size;final long frame,sequence;final byte[] bytes;Packet(byte[] b,byte[] plain){ByteBuffer v=ByteBuffer.wrap(b);type=b[4]&255;flags=b[5]&255;index=v.getShort(6)&65535;count=v.getShort(8)&65535;frame=v.getLong(12);sequence=v.getLong(20);size=v.getInt(28);bytes=plain;}}
 static byte[] nonce(boolean server,long sequence){return ByteBuffer.allocate(12).put((byte)(server?'S':'C')).put((byte)'2').put((byte)(server?'C':'S')).put((byte)'1').putLong(sequence).array();}
 static byte[] seal(byte[] key,boolean server,int type,int flags,int index,int count,long frame,long seq,int size,byte[] payload)throws GeneralSecurityException{if(seq<1||payload.length>CHUNK)throw new IllegalArgumentException();ByteBuffer h=ByteBuffer.allocate(HEADER);h.putInt(0x50435531).put((byte)type).put((byte)flags).putShort((short)index).putShort((short)count).putShort((short)payload.length).putLong(frame).putLong(seq).putInt(size);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce(server,seq)));c.updateAAD(h.array());byte[] out=c.doFinal(payload);return ByteBuffer.allocate(HEADER+out.length).put(h.array()).put(out).array();}
 static Packet open(byte[] key,boolean server,byte[] b)throws GeneralSecurityException{if(b.length<48||b.length>1200||ByteBuffer.wrap(b).getInt()!=0x50435531||(ByteBuffer.wrap(b).getShort(10)&65535)!=b.length-48||ByteBuffer.wrap(b).getLong(20)<1)throw new GeneralSecurityException("Invalid UDP header");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce(server,ByteBuffer.wrap(b).getLong(20))));c.updateAAD(b,0,HEADER);return new Packet(b,c.doFinal(b,HEADER,b.length-HEADER));}
 static final class Replay {final long[] seen=new long[8192];long highest;boolean accept(long n){if(n<1||n<=highest-seen.length||seen[(int)(n&8191)]==n)return false;seen[(int)(n&8191)]=n;highest=Math.max(highest,n);return true;}}
 interface Sink {void frame(byte[] bytes);void loss();}
 static final class Frame {final long id,created;final int flags,size,count;final byte[][] parts;final Map<Integer,byte[]> parity=new HashMap<>();int received;Frame(Packet p,long now){id=p.frame;flags=p.flags;size=p.size;count=p.count;parts=new byte[count][];created=now;}boolean complete(){return received==count;}void add(Packet p){if(p.type==3){if(parts[p.index]==null){parts[p.index]=p.bytes;received++;}}else parity.put(p.index,p.bytes);for(int start=p.index/8*8;start<Math.min(count,p.index/8*8+8);start+=8){byte[] xor=parity.get(start);if(xor==null)continue;int missing=-1,n=0;for(int i=start;i<Math.min(count,start+8);i++)if(parts[i]==null){missing=i;n++;}if(n==1){byte[] restored=xor.clone();for(int i=start;i<Math.min(count,start+8);i++)if(parts[i]!=null)for(int j=0;j<parts[i].length;j++)restored[j]^=parts[i][j];parts[missing]=Arrays.copyOf(restored,Math.min(CHUNK,size-missing*CHUNK));received++;parity.remove(start);}else if(n==0)parity.remove(start);}}
 byte[] bytes(){byte[] b=new byte[size];for(int i=0;i<count;i++)System.arraycopy(parts[i],0,b,i*CHUNK,parts[i].length);return b;}}
 static final class Assembler {final TreeMap<Long,Frame> frames=new TreeMap<>();final Sink sink;long next=-1,completed,lost,lastSkipped=-1;boolean needKey=true;Assembler(Sink value){sink=value;}
 void accept(Packet p,long now){if(p.type!=3&&p.type!=4)return;if(p.frame<1||p.size<4||p.size>MAX_FRAME||p.count!=(p.size+CHUNK-1)/CHUNK||p.index>=p.count||(p.flags&~1)!=0)return;if(p.type==3&&p.bytes.length!=Math.min(CHUNK,p.size-p.index*CHUNK))return;if(p.type==4&&(p.index%8!=0||p.bytes.length!=CHUNK))return;if(next>=0&&p.frame<next)return;if(needKey&&(p.flags&1)==0){if(p.frame!=lastSkipped){lost++;lastSkipped=p.frame;}return;}Frame f=frames.get(p.frame);if(f==null){if(frames.size()>=4){fail();if((p.flags&1)==0)return;}f=new Frame(p,now);frames.put(p.frame,f);}if(f.size!=p.size||f.count!=p.count||f.flags!=p.flags)return;f.add(p);drain(now);}
 void fail(){lost++;needKey=true;frames.clear();sink.loss();}
 void drain(long now){if(needKey){for(Frame f:new ArrayList<>(frames.values()))if(f.complete()&&(f.flags&1)!=0){sink.frame(f.bytes());completed++;next=f.id+1;needKey=false;frames.headMap(next).clear();break;}}if(needKey){if(!frames.isEmpty()&&now-frames.firstEntry().getValue().created>120)fail();return;}while(true){Frame f=frames.get(next);if(f!=null&&f.complete()){sink.frame(f.bytes());completed++;frames.remove(next++);continue;}Frame key=null;for(Frame candidate:frames.values())if(candidate.id>next&&(candidate.flags&1)!=0&&candidate.complete()){key=candidate;break;}if(key!=null){sink.loss();sink.frame(key.bytes());completed++;next=key.id+1;frames.headMap(next).clear();continue;}if(!frames.isEmpty()&&now-frames.firstEntry().getValue().created>120){fail();}break;}}
 }
}
